def build_pool():
    noise = []
    counter = 0
    for (title, source, category, desc, evidence, why, mitre, atlas, risk, flavor, subtype, repeat) in TEMPLATES:
        host_pool = HOSTS_AI if flavor == "ai_attack" else HOSTS_CLASSIC
        user_pool = USERS_AI if flavor == "ai_attack" else USERS_CLASSIC
        for i in range(repeat):
            counter += 1
            host, user, date, time_ = inst(title, host_pool, user_pool, counter)
            # Fold the varying fields into the embedded text itself. Without this,
            # repeated instances of the same template would be LITERALLY identical
            # input text to the embedder (host/user/time are separate JSON fields,
            # not part of what gets embedded) -- producing exact-duplicate vectors
            # that form degenerate micro-clusters and distort every clustering method.
            varied_desc = f"{desc} (Host: {host}; user: {user}; observed {date} {time_}.)"
            noise.append({
                "alert_id": f"NOISE-{counter:04d}",
                "title": title,
                "source": source,
                "severity": "Low" if risk < 20 else ("Medium" if risk < 35 else "High"),
                "time": f"{date} {time_}" if flavor == "ai_attack" else time_,
                "host": host,
                "user": user,
                "category": category,
                "description": varied_desc,
                "evidence": evidence,
                "why_it_matters": why,
                "mitre_techniques": mitre,
                "mitre_atlas_techniques": atlas,
                "risk_score": risk,
                "ground_truth": "noise",
                "noise_subtype": subtype,
                "flavor": flavor,
            })
    return noise

if __name__ == "__main__":
    pool = build_pool()
    out_path = Path(__file__).resolve().parent.parent / "data" / "noise" / "noise_pool.json"
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(pool, indent=2), encoding="utf-8")

    by_subtype = {}
    by_flavor = {}
    for n in pool:
        by_subtype[n["noise_subtype"]] = by_subtype.get(n["noise_subtype"], 0) + 1
        by_flavor[n["flavor"]] = by_flavor.get(n["flavor"], 0) + 1
    print(f"Wrote {len(pool)} noise fragments to {out_path}")
    print("By subtype:", by_subtype)
    print("By flavor:", by_flavor)
